  "settings.linkOpen.current": "\u5F53\u524D\u6807\u7B7E\u9875",
  "settings.linkOpen.tab": "\u65B0\u6807\u7B7E\u9875",
  "settings.linkOpen.split": "\u53F3\u4FA7\u5206\u5C4F",
