  "settings.leftDrag.pan": "\u5E73\u79FB",
  "settings.leftDrag.select": "\u6846\u9009",
  "settings.hover.name": "\u94FE\u63A5\u8282\u70B9\u7684\u60AC\u505C\u9884\u89C8",
