        rowLabel: i === 0 ? t2("headerRows") : void 0,
        title: t2("headerRowsN").replace("{n}", String(i + 1)),
        checked: headRows(tb) === i + 1,
        disabled: headRows(tb) !== i + 1 && !canSetHead(tb, i + 1),
        run: () => keep(setTableLook(this.table, { head: i + 1 }))
